\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.17}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=10cm, height=10cm,
    xlabel={$x$}, ylabel={$y$},
    xmin=-5, xmax=5, ymin=-5, ymax=5,
    axis equal,
    axis lines=middle,
    samples=200,
    domain=0.05:5,
    legend pos=north east,
    title={Trace of $xy=1$ in the $xy$-plane},
    grid=both,
    minor tick num=1,
    every axis plot/.append style={thick}
]
\addplot[blue] {1/x};
\addplot[blue, domain=-5:-0.05] {1/x};
\addplot[green!50!black, dashed, domain=-4:4] {x};
\addplot[red, dashed, domain=-4:4] {-x};
\legend{$xy=1$, , $u$-axis ($y=x$), $v$-axis ($y=-x$)}
\end{axis}
\end{tikzpicture}
\end{document}

\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.17}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=12cm, height=10cm,
    xlabel={$x$}, ylabel={$y$}, zlabel={$z$},
    xmin=-5, xmax=5, ymin=-5, ymax=5, zmin=-3, zmax=3,
    axis lines=middle,
    samples=50,
    samples y=50,
    view={-60}{20},
    colormap/coolwarm,
    title={Surface $xy=1$ in $\mathbb{R}^3$},
    hide axis=false
]
% Parametric surface: (t, 1/t, z)
\addplot3[
    surf,
    shader=flat,
    domain=-5:-0.2,
    y domain=-3:3,
    opacity=0.8
]
({x}, {1/x}, {y});
\addplot3[
    surf,
    shader=flat,
    domain=0.2:5,
    y domain=-3:3,
    opacity=0.8
]
({x}, {1/x}, {y});
% Trace in xy-plane
\addplot3[
    blue,
    thick,
    domain=-5:-0.2,
    samples=100
]
({x}, {1/x}, {0});
\addplot3[
    blue,
    thick,
    domain=0.2:5,
    samples=100
]
({x}, {1/x}, {0});
\end{axis}
\end{tikzpicture}
\end{document}

